import{_ as h,C as r,o as l,c as n,j as d,a as e,E as o,aj as c}from"./chunks/framework.m090XgxO.js";const q=JSON.parse('{"title":"BackTop","description":"","frontmatter":{},"headers":[],"relativePath":"components/back-top.md","filePath":"components/back-top.md","lastUpdated":1789206102000}'),s={name:"components/back-top.md"},b={id:"backtop",tabindex:"-1"};function p(u,t,g,k,x,f){const i=r("Badge"),a=r("XhDemo");return l(),n("div",null,[d("h1",b,[t[0]||(t[0]=e("BackTop ",-1)),o(i,{type:"info",text:"回到顶部"}),t[1]||(t[1]=e()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#backtop","aria-label":'Permalink to "BackTop <Badge type="info" text="回到顶部" />"'},"​",-1))]),t[3]||(t[3]=c('<p>滚过一段距离后露面的按钮，点它滚回顶部。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/back-top" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/back-top.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/back-top" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/back-top" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/back-top.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>滚过 200px 按钮才露面，点它滚回顶部</p>',4)),o(a,{src:"back-top/01-basic"}),t[4]||(t[4]=d("h2",{id:"示例",tabindex:"-1"},[e("示例 "),d("a",{class:"header-anchor",href:"#示例","aria-label":'Permalink to "示例"'},"​")],-1)),t[5]||(t[5]=d("h3",{id:"露面阈值",tabindex:"-1"},[e("露面阈值 "),d("a",{class:"header-anchor",href:"#露面阈值","aria-label":'Permalink to "露面阈值"'},"​")],-1)),t[6]||(t[6]=d("p",null,"visibility-height 决定滚过多少像素按钮才出现",-1)),o(a,{src:"back-top/02-visibility-height"}),t[7]||(t[7]=d("h3",{id:"滚动方式",tabindex:"-1"},[e("滚动方式 "),d("a",{class:"header-anchor",href:"#滚动方式","aria-label":'Permalink to "滚动方式"'},"​")],-1)),t[8]||(t[8]=d("p",null,"behavior=auto 一步跳回顶部，smooth 平滑滚过去",-1)),o(a,{src:"back-top/03-behavior"}),t[9]||(t[9]=d("h3",{id:"语气与尺寸",tabindex:"-1"},[e("语气与尺寸 "),d("a",{class:"header-anchor",href:"#语气与尺寸","aria-label":'Permalink to "语气与尺寸"'},"​")],-1)),t[10]||(t[10]=d("p",null,"tone 决定按钮用哪族颜色，size 换一档尺寸；translations 换掉读屏念出的名字",-1)),o(a,{src:"back-top/04-tone-size"}),t[11]||(t[11]=d("h3",{id:"形态",tabindex:"-1"},[e("形态 "),d("a",{class:"header-anchor",href:"#形态","aria-label":'Permalink to "形态"'},"​")],-1)),t[12]||(t[12]=d("p",null,"variant 换按钮的底色、描边与前景怎么用；这里把露面门槛设成 0，不滚也看得见",-1)),o(a,{src:"back-top/05-variant"}),t[13]||(t[13]=c('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>页面很长且没有别的快速返回方式。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>页面本来就不长：滚过 200px 就出现的按钮只会挡内容。</li><li>需要的是一组动作而不只是回顶：用<a href="./float-button">浮动按钮</a>。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li><code>visibilityHeight</code> 决定滚过多少像素才露面。</li><li><code>behavior</code> 决定一步跳回还是平滑滚过去。</li><li><code>translations</code> 换掉读屏念出的名字。</li><li>缺省触发器与浮动按钮同属 M3 通透玻璃：背景、边缘、高光、柔影和磨砂来自 <code>material.glass</code>；显式 <code>variant</code> 仍按各自语义表面绘制。</li><li>键盘聚焦时触发器改用配方的实体 focus surface，让公共焦点环不依赖背后页面颜色；高对比、减少透明和强制色沿同一令牌通道降级。</li></ul><h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-back-top&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhBackTopRoot</code> <code>XhBackTopTrigger</code></td></tr><tr><td>组合式函数</td><td><code>useBackTop</code></td></tr><tr><td>状态机</td><td><code>backTopMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/back-top.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;back-top&quot;</code>：<strong><code>root</code></strong> · <strong><code>trigger</code></strong></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>visibilityHeight</code></td><td><code>number</code></td><td></td><td>滚过这么多像素按钮才露面，默认 200。</td></tr><tr><td><code>behavior</code></td><td><code>BackTopBehavior</code></td><td></td><td>滚回顶部的方式，默认 smooth。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;BackTopTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>variant</code></td><td><code>ActionVariant</code></td><td></td><td>形态：solid / subtle / outline / ghost，决定底色、描边与前景怎么用。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定按钮用哪族颜色。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。</td></tr><tr><td><code>onVisibilityChange</code></td><td><code>(details: BackTopVisibilityChangeDetails) =&gt; void</code></td><td></td><td>露面与否变化时回调。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>visibility-change</code></td><td><code>BackTopVisibilityChangeDetails</code></td><td>露面与否变化；detail 为 <code>{ visible: boolean }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhBackTopRoot</code></td><td><code>default</code></td><td><code>BackTopRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr><tr><td><code>trigger</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>hidden</code> · <code>visible</code></p><p><strong>事件</strong>：<code>SCROLL.RESOLVE</code> · <code>TRIGGER.CLICK</code></p><p><strong>判据</strong>：<code>shouldShow</code> · <code>shouldHide</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useBackTop</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>visible</code></td><td><code>boolean</code></td><td>按钮此刻露不露面。</td></tr><tr><td><code>scrollToTop</code></td><td><code>() =&gt; void</code></td><td>程序化滚回顶部，与点按钮走同一条路。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/button/" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Enter</code> / <code>Space</code></td><td>focus in trigger</td><td>滚回顶部；按 behavior 决定是一步到位还是平滑滚过去</td></tr><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>trigger 露面时</td><td>走到按钮上；收起时整个 root 带 hidden，按钮不在 Tab 序列里</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>trigger</code></td><td><code>aria-label</code></td><td>props.translations.trigger</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/back-top.css</code> 按部件选择：<code>[data-scope=&quot;back-top&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>root</code></td><td><code>data-variant</code></td><td>props.variant</td></tr><tr><td><code>trigger</code></td><td><code>data-state</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；缺省来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>缺省来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-back-top-bg</code></td><td><code>trigger</code></td><td><code>background-color</code></td><td><code>default</code></td><td><code>--xh-_back-top-bg</code></td><td>back-top 的 trigger 部件 background-color 覆盖槽。</td></tr><tr><td><code>--xh-back-top-bg-active</code></td><td><code>trigger</code></td><td><code>background-color</code></td><td><code>active</code></td><td><code>--xh-_back-top-bg-active</code></td><td>back-top 的 trigger 部件 background-color 覆盖槽。</td></tr><tr><td><code>--xh-back-top-bg-hover</code></td><td><code>trigger</code></td><td><code>background-color</code></td><td><code>@media (hover: hover)</code><br><code>hover</code></td><td><code>--xh-_back-top-bg-hover</code></td><td>back-top 的 trigger 部件 background-color 覆盖槽。</td></tr><tr><td><code>--xh-back-top-border</code></td><td><code>trigger</code></td><td><code>border</code></td><td><code>default</code></td><td><code>--xh-_back-top-border</code></td><td>back-top 的 trigger 部件 border 覆盖槽。</td></tr><tr><td><code>--xh-back-top-border-hover</code></td><td><code>trigger</code></td><td><code>border-color</code></td><td><code>@media (hover: hover)</code><br><code>hover</code></td><td><code>--xh-_back-top-border-hover</code></td><td>back-top 的 trigger 部件 border-color 覆盖槽。</td></tr><tr><td><code>--xh-back-top-fg</code></td><td><code>trigger</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-_back-top-fg</code></td><td>back-top 的 trigger 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-back-top-icon-size</code></td><td><code>root</code></td><td><code>--xh-icon-size</code></td><td><code>default</code></td><td><code>--xh-glyph-size-text</code></td><td>back-top 的 root 部件 --xh-icon-size 覆盖槽。</td></tr><tr><td><code>--xh-back-top-inset-block</code></td><td><code>root</code></td><td><code>inset-block-end</code></td><td><code>default</code></td><td><code>--xh-space-8</code></td><td>back-top 的 root 部件 inset-block-end 覆盖槽。</td></tr><tr><td><code>--xh-back-top-inset-inline</code></td><td><code>root</code></td><td><code>inset-inline-end</code></td><td><code>default</code></td><td><code>--xh-space-8</code></td><td>back-top 的 root 部件 inset-inline-end 覆盖槽。</td></tr><tr><td><code>--xh-back-top-layer</code></td><td><code>root</code></td><td><code>z-index</code></td><td><code>default</code></td><td><code>--xh-layer-sticky</code></td><td>back-top 的 root 部件 z-index 覆盖槽。</td></tr><tr><td><code>--xh-back-top-radius</code></td><td><code>trigger</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-pill</code></td><td>back-top 的 trigger 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-back-top-shadow</code></td><td><code>trigger</code></td><td><code>box-shadow</code></td><td><code>default</code></td><td><code>--xh-_back-top-shadow</code></td><td>back-top 的 trigger 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-back-top-size</code></td><td><code>trigger</code></td><td><code>block-size</code><br><code>inline-size</code></td><td><code>default</code></td><td><code>--xh-_back-top-size</code></td><td>back-top 的 trigger 部件 block-size、inline-size 覆盖槽。</td></tr></tbody></table><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p><code>background</code> · <code>border-color</code> · <code>scale</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="响应式" tabindex="-1">响应式 <a class="header-anchor" href="#响应式" aria-label="Permalink to &quot;响应式&quot;">​</a></h2><p>皮肤另按输入能力分档：<code>hover: hover</code> · <code>pointer: coarse</code>——同一份皮肤在触屏与带指针的设备上不一样，与视口宽度无关。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>与<a href="./scroll-area">滚动区域</a>配合时把滚动容器指给它，别让它盯着窗口。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>位置要躲开固定工具条与移动端手势区。</li><li>平滑滚动对晕动敏感的用户不友好，系统开了减弱动效时应退回一步跳回。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>恒显：没滚动时它没有意义，只是一块遮挡。</li><li>在短页面上加它。</li></ul>',57))])}const v=h(s,[["render",p]]);export{q as __pageData,v as default};
